3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\ValidatesShopifyWebhookHmac;
7	use App\Jobs\Shopify\Gdpr\ExportCustomerDataJob;
8	use App\Jobs\Shopify\Gdpr\RedactCustomerJob;
9	use App\Jobs\Shopify\Gdpr\RedactShopJob;
10	use App\Models\Core\Gdpr\GdprRequest;
11	use Illuminate\Http\JsonResponse;
12	use Illuminate\Http\Request;
13	use Illuminate\Support\Facades\Log;
14	
15	// V2: Receives Shopify GDPR webhooks. Validates HMAC, writes an idempotent
16	// audit row, dispatches a dedicated job per topic onto the `gdpr` queue,
17	// returns 202. Invalid HMAC returns 401 — returning 200 on a bad signature
18	// is a silent-acceptance vuln.
19	class ShopifyGdprWebhookController extends ApiController
20	{
21	    use ValidatesShopifyWebhookHmac;
22	
23	    public function customersDataRequest(Request $request): JsonResponse
24	    {
25	        return $this->handleGdprWebhook($request, GdprRequest::TOPIC_CUSTOMERS_DATA_REQUEST);
26	    }
27	
28	    public function customersRedact(Request $request): JsonResponse
29	    {
30	        return $this->handleGdprWebhook($request, GdprRequest::TOPIC_CUSTOMERS_REDACT);
31	    }
32	
33	    public function shopRedact(Request $request): JsonResponse
34	    {
35	        return $this->handleGdprWebhook($request, GdprRequest::TOPIC_SHOP_REDACT);
36	    }
37	
38	    private function handleGdprWebhook(Request $request, string $topic): JsonResponse
39	    {
40	        $rawBody = (string) $request->getContent();
41	        $signature = (string) $request->header('X-Shopify-Hmac-SHA256', '');
42	        $shopDomain = mb_strtolower(trim((string) $request->header('X-Shopify-Shop-Domain', '')));
43	
44	        if (! $this->isValidShopifyHmac($rawBody, $signature)) {
45	            Log::warning("Shopify GDPR webhook ({$topic}): invalid HMAC signature", [
46	                'shop_domain' => $shopDomain,
47	            ]);
48	
49	            return $this->error('invalid signature', 401);
50	        }
51	
52	        $payload = json_decode($rawBody, true) ?: [];
53	        $hash = hash('sha256', $rawBody);
54	
55	        // firstOrCreate on payload_hash gives us Shopify-retry idempotency:
56	        // the unique index fails insert on a duplicate, Eloquent fetches the
57	        // existing row, wasRecentlyCreated=false and we skip dispatch.
58	        $audit = GdprRequest::firstOrCreate(
59	            ['payload_hash' => $hash],
60	            [
61	                'topic' => $topic,
62	                'shop_domain' => $shopDomain,
63	                'shopify_shop_id' => is_numeric($payload['shop_id'] ?? null) ? (int) $payload['shop_id'] : null,
64	                'payload' => $payload,
65	                'status' => GdprRequest::STATUS_RECEIVED,
66	                'received_at' => now(),
67	            ],
68	        );
69	
70	        if ($audit->wasRecentlyCreated) {
71	            match ($topic) {
72	                GdprRequest::TOPIC_CUSTOMERS_DATA_REQUEST => ExportCustomerDataJob::dispatch($audit->id),
73	                GdprRequest::TOPIC_CUSTOMERS_REDACT => RedactCustomerJob::dispatch($audit->id),
74	                GdprRequest::TOPIC_SHOP_REDACT => RedactShopJob::dispatch($audit->id),
75	            };
76	
77	            Log::info("Shopify GDPR webhook accepted: {$topic}", [
78	                'gdpr_request_id' => $audit->id,
79	                'shop_domain' => $shopDomain,
80	            ]);
81	        } else {
82	            Log::info("Shopify GDPR webhook deduplicated: {$topic}", [
83	                'gdpr_request_id' => $audit->id,
84	                'shop_domain' => $shopDomain,
85	            ]);
86	        }
87	
88	        return $this->success(['received' => true], 202);
89	    }
90	}
